            client_ip,
            client_port,
            application,
            operation,
            schema_name,
            table_name,
            record_id,
            old_data,
            new_data
        )
        VALUES (
            current_user,
            session_user,
            inet_client_addr(),
            inet_client_port(),
            current_setting('application_name', true),
            TG_OP,
            TG_TABLE_SCHEMA,
            TG_TABLE_NAME,
            NULL,
            NULL,
            v_new
        );

        RETURN NEW;

    ELSIF TG_OP = 'UPDATE' THEN

        v_old := to_jsonb(OLD);
        v_new := to_jsonb(NEW);

        INSERT INTO audit.data_changes (
            db_user,
