            inet_client_addr(),
            inet_client_port(),
            current_setting('application_name', true),
            TG_OP,
            TG_TABLE_SCHEMA,
            TG_TABLE_NAME,
            NULL,
            v_old,
            v_new
        );

        RETURN NEW;

    ELSIF TG_OP = 'DELETE' THEN

        v_old := to_jsonb(OLD);

        INSERT INTO audit.data_changes (
            db_user,
            session_db_user,
            client_ip,
            client_port,
            application,
