--
-- Name: create_user_activity_audit_partition(date); Type: FUNCTION; Schema: core; Owner: postgres
--

CREATE FUNCTION core.create_user_activity_audit_partition(p_month_start date) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    partition_name TEXT;
    month_end      DATE;
BEGIN
    partition_name := 'user_activity_audit_' || to_char(p_month_start, 'YYYY_MM');
    month_end := (p_month_start + INTERVAL '1 month')::DATE;
    EXECUTE format(
            'CREATE TABLE IF NOT EXISTS core.%I PARTITION OF core.user_activity_audit FOR VALUES FROM (%L) TO (%L)',
            partition_name,
            p_month_start,
            month_end);
END;
$$;


ALTER FUNCTION core.create_user_activity_audit_partition(p_month_start date) OWNER TO postgres;

--
-- Name: ensure_user_activity_audit_partitions(integer); Type: FUNCTION; Schema: core; Owner: postgres
--

CREATE FUNCTION core.ensure_user_activity_audit_partitions(months_ahead integer DEFAULT 3) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    start_month DATE;
    end_month   DATE;
    m           DATE;
BEGIN
    start_month := date_trunc('month', (NOW() AT TIME ZONE 'UTC') - INTERVAL '1 month')::DATE;
    end_month := date_trunc('month', (NOW() AT TIME ZONE 'UTC') + make_interval(months => months_ahead))::DATE;
    m := start_month;
    WHILE m <= end_month
        LOOP
            PERFORM core.create_user_activity_audit_partition(m);
            m := (m + INTERVAL '1 month')::DATE;
        END LOOP;
END;
$$;


