CREATE FUNCTION core.fn_audit_row_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'core', 'pg_temp'
    AS $$
DECLARE
    v_terminal TEXT;
    v_payload  JSONB;
BEGIN
    v_terminal := COALESCE(inet_client_addr()::TEXT, 'local')
        || CASE
               WHEN NULLIF(current_setting('application_name', true), '') IS NOT NULL
                   THEN ' · ' || current_setting('application_name', true)
               ELSE ''
           END;

    IF TG_OP = 'DELETE' THEN
        v_payload := jsonb_build_object('old', to_jsonb(OLD));
        INSERT INTO core.db_change_audit (db_user, terminal, db_object, operation, data_changed)
        VALUES (session_user, v_terminal, TG_TABLE_SCHEMA || '.' || TG_TABLE_NAME, TG_OP, v_payload);
        RETURN OLD;
    ELSIF TG_OP = 'UPDATE' THEN
        v_payload := jsonb_build_object('old', to_jsonb(OLD), 'new', to_jsonb(NEW));
        INSERT INTO core.db_change_audit (db_user, terminal, db_object, operation, data_changed)
        VALUES (session_user, v_terminal, TG_TABLE_SCHEMA || '.' || TG_TABLE_NAME, TG_OP, v_payload);
        RETURN NEW;
    ELSE
        v_payload := jsonb_build_object('new', to_jsonb(NEW));
        INSERT INTO core.db_change_audit (db_user, terminal, db_object, operation, data_changed)
        VALUES (session_user, v_terminal, TG_TABLE_SCHEMA || '.' || TG_TABLE_NAME, TG_OP, v_payload);
        RETURN NEW;
    END IF;
END;
$$;


